# ---- new module-level builders (spliced into build2.py) ----
SWATCH=lambda c,w=28: f'<span style="display:inline-block;width:{w}px;height:{w}px;border-radius:50%;background:{c};border:2px solid #fff;box-shadow:0 0 0 1.5px #dadce0;vertical-align:middle"></span>'
def cbx(label,on=True,note=""):
    return f'<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;border:1.5px solid {"#a8c7fa" if on else "#e8eaed"};background:{"#f3f8ff" if on else "#fff"};border-radius:14px"><div style="width:22px;height:22px;border-radius:6px;flex-shrink:0;border:2px solid {"#1a73e8" if on else "#bdc1c6"};background:{"#1a73e8" if on else "#fff"};color:#fff;font-size:14px;text-align:center;line-height:18px">{"✓" if on else ""}</div><div><div style="font-size:14px;font-weight:{600 if on else 500}">{label}</div>{f"<div class=mini style=font-size:11.5px>{note}</div>" if note else ""}</div></div>'
def plan_pill(code,name,col,on=True):
    return f'<span style="display:inline-flex;align-items:center;gap:8px;padding:8px 16px;border-radius:22px;font-size:13.5px;font-weight:700;background:{col if on else "#fff"};color:{"#fff" if on else "#5f6368"};border:1.5px solid {col if on else "#dadce0"}">{"✓ " if on else ""}{code}<span style="font-weight:500;font-size:12px;opacity:.9">{name}</span></span>'
def page_new_entry(ctx):
    isl=ctx['island']
    def sec(n,title,hint,inner,right=""):
        return f'<div class=card><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px"><div style="display:flex;gap:12px;align-items:center"><span class=badge style="width:30px;height:30px;font-size:13px">{n}</span><div><h3 style="font-size:17px">{title}</h3><div class=mini>{hint}</div></div></div>{right}</div>{inner}</div>'
    req=lambda t:f'<span style="color:#d93025">*</span> {t}'
    s1=sec(1,"Island, class and star","Decides which island, class and star list this hotel goes into",f'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px">{fld(req("Island"),isl+" ▾")}{fld(req("Class"),"Mid ▾")}{fld("Star","4 ★ ▾")}</div>')
    s2=sec(2,"Hotel name & personal ID","Same as the top of every hotel sheet",f'{fld(req("Hotel name"),"SAMPLE BAY RESORT")}<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px">{fld(req("Mobile no"),"9999900000, 03192-000000")}{fld("Email ID","reservations@samplebay.com")}</div><div style="margin-top:12px">{fld("Address",isl)}</div>',"<span class='tag t-g'>Sample data</span>")
    plans=plan_pill("EP","Room only","#5f6368")+plan_pill("CP","With breakfast","#1a73e8")+plan_pill("MAP","Breakfast + 1 meal","#34a853")+plan_pill("AP","All meals","#ea4335")+plan_pill("SP1","Honeymoon Package","#9334e6")+'<span style="display:inline-flex;align-items:center;padding:8px 16px;border-radius:22px;font-size:13.5px;font-weight:700;border:1.5px dashed #1a73e8;color:#1a73e8">＋ Add plan type</span>'
    newplan=f'<div style="margin:14px 0;padding:16px 18px;border-radius:16px;background:#f6effd;border:1.5px solid #e1c9f8"><div style="display:flex;justify-content:space-between;margin-bottom:10px"><b style="color:#7b1fa2">Add a new plan type</b><span class=mini>Saved in Settings → Plan types, so every hotel can use it</span></div><div style="display:grid;grid-template-columns:110px 1fr 1fr auto;gap:12px;align-items:end">{fld("Short code","SP2")}{fld("Full name","Peak Season Package")}<div><div class=lbl>Colour</div><div style="display:flex;gap:8px;height:44px;align-items:center">{SWATCH("#9334e6")}{SWATCH("#f29900")}{SWATCH("#12b5cb")}{SWATCH("#e52592")}{SWATCH("#188038")}</div></div><span class="btn" style="background:#9334e6">Add</span></div></div>'
    TH=lambda t,c="#1967d2":f'<th style="text-align:right;color:{c}">{t}</th>'
    def row(c,t,ep,cp,mp,ap,sp): return f'<tr><td>{ein(c,"230px")}</td><td>{ein(t,"70px","right")}</td><td>{ein(ep,"80px","right")}</td><td>{ein(cp,"90px","right")}</td><td>{ein(mp,"80px","right")}</td><td>{ein(ap,"80px","right")}</td><td>{ein(sp,"90px","right")}</td><td><span class="tag t-n">🗑</span></td></tr>'
    rows=row("DELUXE ROOM","10","—","4,800","—","—","—")+row("SUPER DELUXE ROOM","8","—","5,600","7,100","8,600","12,500")+row("SUITE ROOM","4","—","7,200","—","—","—")
    s3=sec(3,"Room categories & rates","Type each category once, then fill the plans this hotel offers — leave a plan empty if not offered",
      f'<div class=lbl style="margin-bottom:10px">Plan types shown in the table (tick / untick)</div><div style="display:flex;gap:10px;flex-wrap:wrap">{plans}</div>{newplan}<table><tr><th>CATEGORY</th><th style="text-align:right">TOTAL ROOMS</th>{TH("EP")}{TH("CP")}{TH("MAP")}{TH("AP")}{TH("SP1 · Honeymoon","#7b1fa2")}<th></th></tr>{rows}</table><div style="margin-top:12px"><span class="btn ghost" style="padding:8px 18px">+ Add room category</span> <span class=mini style="margin-left:10px">or pick from your list: Deluxe Room · Premium Room · Family Room · Suite Room …</span></div>',"")
    ai=lambda a,r:f'{ein(a)}{ein(r,"100%","right")}<span class="tag t-n">🗑</span>'
    s4=sec(4,"Add-ons / extra rates","Flower bed, candle light dinner, cake, extra mattress, meals …",f'<div style="margin-bottom:12px">{seg(["ADD ON BENEFITS","EXTRA RATE"],0)}</div><div style="display:grid;grid-template-columns:1fr 160px 40px;gap:10px;align-items:center">{ai("Extra mattress per person","₹ 1,500")}{ai("Flower bed decoration","₹ 3,000")}{ai("Candle light dinner","₹ 4,500")}</div><div style="margin-top:12px"><span class="btn ghost" style="padding:8px 18px">+ Add item</span> <span class=mini style="margin-left:10px">or choose from your add-on list ▾ (managed in Settings)</span></div>')
    fac=[("Swimming pool",True,"Goes to the Pool list"),("Sea view",True,"Goes to the Sea view list"),("Beach front",False,""),("Restaurant",True,""),("Bar / wine",False,""),("Wi-Fi",True,""),("Free parking",True,""),("Spa / massage",False,""),("Gym",False,""),("Lift",False,""),("Bathtub rooms",False,""),("Private balcony",False,""),("Kids play area",False,""),("Pet friendly",False,""),(f"{'Jetty' if isl!='Port Blair' else 'Airport'} pickup",True,""),("Candle light dinner area",False,"")]
    s5=sec(5,"Facilities","Tick every facility this hotel has — the hotel is added to the matching lists",'<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px">'+"".join(cbx(a,b,c) for a,b,c in fac)+'</div><div style="margin-top:14px"><span class="btn ghost" style="padding:8px 18px">+ Add a new facility</span> <span class=mini style="margin-left:10px">Facility list is managed in Settings → Facilities</span></div>')
    chips=lambda items:"".join(f'<span class="tag t-b" style="margin:3px 4px 3px 0">{x}</span>' for x in items)
    s6=sec(6,"Submit to categories","Check where this hotel will appear, then press Submit",f'<div style="display:grid;grid-template-columns:150px 1fr;row-gap:12px;font-size:14px;align-items:center"><b>Island</b><div>{chips([isl])}</div><b>Class</b><div>{chips(["Mid"])}</div><b>Star list</b><div>{chips(["4 STAR"])}</div><b>Price range</b><div>{chips(["₹4,100 – ₹5,000","₹5,100 – ₹20,000"])}</div><b>Facility lists</b><div>{chips(["Pool","Sea view","Restaurant","Wi-Fi","Free parking","Pickup"])}</div><b>Also updated</b><div>{chips(["Hotel dropdown","All Hotels page","Dashboard counts","Low-price ranking"])}</div></div><div style="display:flex;gap:12px;margin-top:22px"><span class="btn" style="padding:14px 34px;font-size:15px">✅ Submit &amp; Update All Hotels</span><span class="btn ghost" style="padding:14px 28px">💾 Save as draft</span><span class="btn red" style="padding:14px 28px">Clear form</span></div>')
    done=lambda t,ok=True,opt=False:f'<div style="display:flex;gap:10px;padding:8px 0;align-items:center;font-size:14px"><span class=badge style="width:22px;height:22px;font-size:12px;background:{"#34a853" if ok else "#dadce0"}">{"✓" if ok else ""}</span><span style="flex:1;{"" if ok else "color:#80868b"}">{t}</span>{"<span class=mini>optional</span>" if opt else ""}</div>'
    side=f"""<div class=grid style="align-content:start;position:sticky;top:20px"><div class=card style="border-top:5px solid #34a853"><div style="display:flex;justify-content:space-between;align-items:center"><h3>✅ Ready to submit?</h3><span class="tag t-y">5 of 5</span></div>
<div class=mini style="margin:8px 0 12px;line-height:1.5">A to-do list for this form. Each line turns <b style="color:#137333">green</b> when you fill it. When all <b>required</b> lines are green, the Submit button works. “Optional” lines can stay empty.</div>
<div class=lbl>Required</div>{done("Island chosen")}{done("Class chosen")}{done("Hotel name")}{done("Mobile number")}{done("1 room category with a price")}<div class=lbl style="margin-top:12px">Optional</div>{done("Email &amp; address",True,True)}{done("Add-on rates",True,True)}{done("Facilities ticked",True,True)}{done("Star chosen",True,True)}
<div style="margin-top:14px;padding:12px;border-radius:12px;background:#e6f4ea;color:#137333;font-weight:600;font-size:13.5px;text-align:center">All required items done — you can submit</div></div>
<div class=card style="background:#fef7e0"><b style="color:#7a5a00">If something is missing</b><div class=mini style="margin-top:6px;color:#7a5a00;line-height:1.5">That line stays grey, the Submit button is greyed out, and the field that needs filling is highlighted in red.</div></div></div>"""
    body=f'<div class=card style="background:#e8f0fe;margin-bottom:18px;padding:16px 24px;display:flex;gap:14px;align-items:center"><span style="font-size:22px">📝</span><div style="color:#1967d2;font-size:14px;line-height:1.5"><b>Fill everything on this one page</b> — top to bottom. Boxes marked <span style="color:#d93025">*</span> are required. The checklist on the right shows what is still missing.</div></div><div class=grid style="grid-template-columns:1.9fr 1fr;align-items:start"><div class=grid style="align-content:start">{s1}{s2}{s3}{s4}{s5}{s6}</div>{side}</div>'
    return page('new','New Hotel Entry','One page · same format as every hotel sheet · pick facilities and submit',body,ctx,"All on one page")
def page_update_all(ctx):
    isl=ctx['island']; allh=[h for h in ALL if h['island']==isl]; n0=len(allh); m0=sum(1 for h in allh if h['tier']=='Mid')
    def upd(t,d,b,a,on=True): return f'<div style="display:flex;align-items:center;gap:16px;padding:14px 0;border-bottom:1px solid #f1f3f4"><div style="width:22px;height:22px;border-radius:6px;background:{"#1a73e8" if on else "#fff"};border:2px solid {"#1a73e8" if on else "#dadce0"};color:#fff;font-size:14px;text-align:center;line-height:18px">{"✓" if on else ""}</div><div style="flex:1"><div class=hname>{t}</div><div class=mini>{d}</div></div><div style="text-align:right;font-size:13px;white-space:nowrap"><span style="color:#80868b">{b}</span> <b style="color:#34a853">→ {a}</b></div></div>'
    ups=(upd(f"{isl} hotel list (Home &amp; Find dropdown)","SAMPLE BAY RESORT added",f"{n0} hotels",f"{n0+1} hotels")+upd("Hotel rate card page","New page: rates (EP, CP, MAP, AP, SP1), contact, add-ons","—","1 new page")+upd("Class: Mid",f"Counted under Mid for {isl}",f"{m0} Mid",f"{m0+1} Mid")+upd("All Hotels page &amp; Dashboard counts","Card added · totals updated",f"{n0}",f"{n0+1}")+upd("Price range lists","₹4,100–5,000 and ₹5,100+ rows added","","+3 rows")+upd("Star category: 4 STAR","Added under 4 STAR HOTELS","","+1")+upd("Facility lists — Pool, Sea view","Ticked facilities","","+2 lists")+upd("Facility lists — Restaurant, Wi-Fi, Parking, Pickup","New lists, shown only if switched on in Settings → Facilities","","+4 lists",False)+upd("Top rankings","Low-price Top 5 recalculated from rates","","auto"))
    body=f"""<div class=card style="background:#e6f4ea;margin-bottom:18px;padding:16px 24px;display:flex;gap:14px;align-items:center"><span style="font-size:22px">👀</span><div style="color:#137333;font-size:14px"><b>Last check before saving.</b> You pressed Submit on the New Hotel Entry page — these are the lists that will change. Untick anything you do not want.</div></div>
<div class=grid style="grid-template-columns:1.6fr 1fr;align-items:start"><div class=card><h3 style="margin-bottom:4px">These pages will be updated</h3>{ups}</div><div class=grid style="align-content:start"><div class=card><div class=lbl>New hotel</div><h2 style="font-size:20px;margin-bottom:12px">SAMPLE BAY RESORT</h2><table><tr><td>Island</td><td class=num>{isl}</td></tr><tr><td>Class</td><td class=num>{tag("Mid")}</td></tr><tr><td>Star</td><td class=num>4 ★</td></tr><tr><td>Starting rate</td><td class=num>₹4,800</td></tr><tr><td>Plans used</td><td class=num>CP · MAP · AP · SP1</td></tr><tr><td>Facilities</td><td class=num>6 ticked</td></tr></table></div>
<div class=card style="background:#e6f4ea"><div style="display:flex;gap:12px;align-items:center"><span style="font-size:26px">✅</span><div><div class=hname style="color:#137333">No problems found</div><div class=mini style="color:#137333">Name is new · rates are numbers · contact filled</div></div></div></div><div class=card><span class="btn" style="display:block;text-align:center;font-size:15px;padding:14px">🔄 Update All Hotels</span><div style="height:10px"></div><span class="btn ghost" style="display:block;text-align:center">← Back to edit</span><div class=mini style="margin-top:12px;text-align:center">A backup is taken before updating, so you can undo.</div></div></div></div>"""
    return page('update','Update All Hotels','Final check — add the new hotel to every list in one click',body,ctx,"Last step")
# ---------------- SETTINGS ----------------
SMENU=[("LOOK & FEEL",[("Colors & Theme","🎨"),("Fonts & Layout","🔤"),("Name & Logo","🏷️")]),("HOTEL ENTRY OPTIONS",[("Plan types (EP, CP, MAP, AP, SP…)","🍽️"),("Room categories","🛏️"),("Add-on items","🎂"),("Facilities","🏊")]),("ORGANISE",[("Classes (High / Mid / Low)","🏷️"),("Islands","🏝️"),("Star categories","★"),("Price ranges","₹"),("Rankings","🏆")]),("DATA & SAFETY",[("Company info","ℹ️"),("Backup & Restore","💾"),("Import / Export Excel","📤"),("Password & access","🔒")])]
def settings_page(active,title,sub,body,ctx):
    m=""
    for g,items in SMENU:
        m+=f'<div class=lbl style="margin:16px 0 6px 6px">{g}</div>'
        for n,ic in items:
            on=n.startswith(active)
            m+=f'<div style="padding:10px 12px;border-radius:12px;font-size:13.5px;font-weight:{600 if on else 500};display:flex;gap:10px;{"background:#e8f0fe;color:#1967d2" if on else "color:#3c4043"}"><span style="width:20px;text-align:center">{ic}</span>{n}</div>'
    inner=f'<div style="display:grid;grid-template-columns:290px 1fr;gap:18px;align-items:start"><div class=card style="padding:10px 14px 18px">{m}</div><div class=grid style="align-content:start">{body}</div></div>'
    return page('settings',title,sub,inner,ctx,"Applies to all islands",bar=False)
def colrow(label,hexv,note=""):
    return f'<div style="display:flex;align-items:center;gap:14px;padding:10px 0;border-bottom:1px solid #f1f3f4"><div style="flex:1"><div style="font-size:14px;font-weight:600">{label}</div>{f"<div class=mini>{note}</div>" if note else ""}</div>{SWATCH(hexv,34)}<div class=inp style="min-height:36px;padding:7px 12px;width:110px;font-family:monospace;font-size:13px">{hexv.upper()}</div></div>'
def page_settings_colors(ctx):
    themes=[("Google Blue","#1a73e8","#fbbc04",True),("Ocean Teal","#0e7c86","#e0a93b",False),("Sunset Orange","#e8710a","#fbbc04",False),("Royal Purple","#7b1fa2","#f9ab00",False),("Forest Green","#188038","#fbbc04",False),("Rose Pink","#d01884","#f9ab00",False),("Dark Night","#8ab4f8","#fdd663",False),("Your own colours","#5f6368","#9aa0a6",False)]
