def page_settings_fac(ctx):
    facs=[("🏊","Swimming pool","Pool list",True,True),("🌊","Sea view","Sea view list",True,True),("🏖️","Beach front","",True,False),("🍽️","Restaurant","",True,False),("🍷","Bar / wine","",False,False),("📶","Wi-Fi","",True,False),("🅿️","Free parking","",True,False),("💆","Spa / massage","",False,False),("🏋️","Gym","",False,False),("🛁","Bathtub rooms","",False,False),("🐾","Pet friendly","",False,False)]
    fr="".join(f'<tr><td style="font-size:20px;width:36px">{i}</td><td class=hname>{n}</td><td class=mini>{("Existing list: "+l) if l else "Creates its own list"}</td><td>{"<span class=\"tag t-y\">List page ON</span>" if lp else "<span class=\"tag t-n\">List page off</span>"}</td><td>{"<span class=\"tag t-y\">Filter ON</span>" if fl else "<span class=\"tag t-n\">Filter off</span>"}</td><td><span class="tag t-n">✏️</span> <span class="tag t-n">🗑</span></td></tr>' for i,n,l,lp,fl in facs)
    adds=[("Flower bed decoration","3,000"),("Candle light dinner","4,000"),("Cake","1,200"),("Extra mattress","1,500"),("Meal per person","950"),("Extra person","1,400"),("Extra child","1,000"),("Late checkout","1,500"),("Gala dinner (New Year / Christmas)","2,000"),("Honeymoon decoration","2,500")]
    ar="".join(f'<tr><td class=hname>{a}</td><td class=num>₹{b}</td><td class=mini>Default rate · you can change it per hotel</td><td><span class="tag t-n">✏️</span> <span class="tag t-n">🗑</span></td></tr>' for a,b in adds)
    t=f"""<div class=card><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px"><div><h3>Facilities</h3><div class=mini>These are the tick-boxes at the bottom of New Hotel Entry. Switch “List page” on to get a page of all hotels with that facility.</div></div><span class="btn">＋ Add facility</span></div><table style="margin-top:12px"><tr><th></th><th>FACILITY</th><th>LINKED TO</th><th>LIST PAGE</th><th>FILTER</th><th></th></tr>{fr}</table>
<div style="display:grid;grid-template-columns:70px 1fr auto;gap:12px;margin-top:16px;align-items:end">{fld("Icon","🧖")}{fld("New facility name","e.g. Sauna")}<span class="btn ghost">Add</span></div></div>
<div class=card><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px"><div><h3>Add-on items library</h3><div class=mini>Pick these while entering a hotel instead of typing each time</div></div><span class="btn">＋ Add item</span></div><table style="margin-top:12px"><tr><th>ITEM</th><th style="text-align:right">DEFAULT RATE</th><th>NOTE</th><th></th></tr>{ar}</table></div>
<div class=card style="display:flex;gap:10px"><span class="btn">💾 Save changes</span><span class="btn ghost">Cancel</span></div>"""
    return settings_page("Facilities","Settings · Facilities & Add-on items","Everything you can tick or pick on the New Hotel Entry page",t,ctx)
def page_settings_org(ctx):
    cl=[("High","#fbbc04",17),("Mid","#1a73e8",26),("Low","#34a853",22),("Budget","#12b5cb",0)]
    cr="".join(f'<tr><td>{SWATCH(c,24)}</td><td class=hname>{n}</td><td class=num>{k} hotels</td><td>{"<span class=\"tag t-n\">Built-in</span>" if n!="Budget" else "<span class=\"tag\" style=\"background:#f6effd;color:#7b1fa2\">Custom</span>"}</td><td><span class="tag t-n">✏️</span>{"" if n!="Budget" else " <span class=\"tag t-n\">🗑</span>"}</td></tr>' for n,c,k in cl)
    isl=[("Port Blair","South Andaman · near airport",65),("Havelock","Swaraj Dweep · near jetty",23),("Neil","Shaheed Dweep · near jetty",18),("Little Andaman","Custom · near jetty",0)]
    ir="".join(f'<tr><td class=hname>{n}</td><td class=mini>{d}</td><td class=num>{k} hotels</td><td><span class="tag t-n">✏️</span>{"" if n!="Little Andaman" else " <span class=\"tag t-n\">🗑</span>"}</td></tr>' for n,d,k in isl)
    pr="".join(f'<tr><td class=hname>{a}</td><td class=num>₹{b:,}</td><td class=num>₹{c:,}</td><td><span class="tag t-n">✏️</span> <span class="tag t-n">🗑</span></td></tr>' for a,b,c in [("Band 1",1000,2000),("Band 2",2100,3000),("Band 3",3100,4000),("Band 4",4100,5000),("Band 5",5100,20000)])
    t=f"""<div style="display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start"><div class=card><div style="display:flex;justify-content:space-between;align-items:center"><h3>Classes</h3><span class="btn" style="padding:8px 18px">＋ Add class</span></div><div class=mini style="margin:4px 0 8px">Rename, recolour or add your own (e.g. Budget, Luxury)</div><table><tr><th></th><th>NAME</th><th style="text-align:right">IN USE</th><th>TYPE</th><th></th></tr>{cr}</table></div>
<div class=card><div style="display:flex;justify-content:space-between;align-items:center"><h3>Islands</h3><span class="btn" style="padding:8px 18px">＋ Add island</span></div><div class=mini style="margin:4px 0 8px">Each island gets its own tab at the top</div><table><tr><th>NAME</th><th>NOTE</th><th style="text-align:right">IN USE</th><th></th></tr>{ir}</table></div></div>
<div style="display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start"><div class=card><div style="display:flex;justify-content:space-between;align-items:center"><h3>Price ranges</h3><span class="btn" style="padding:8px 18px">＋ Add range</span></div><div class=mini style="margin:4px 0 8px">The bands used on the Price Range page</div><table><tr><th>BAND</th><th style="text-align:right">FROM</th><th style="text-align:right">TO</th><th></th></tr>{pr}</table></div>
<div class=card><h3 style="margin-bottom:6px">Rankings &amp; stars</h3>{tog("Low-price list worked out automatically",True,"From the actual rates — no typing mistakes")}{tog("Show 3 / 4 / 5 star lists",True)}{tog("Show 2 star list",False)}<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px">{fld("Top how many hotels?","5 ▾")}{fld("‘Near’ label","Airport / Jetty (per island) ▾")}</div></div></div>
<div class=card style="display:flex;gap:10px"><span class="btn">💾 Save changes</span><span class="btn ghost">Cancel</span></div>"""
    return settings_page("Classes","Settings · Classes, Islands, Price ranges & Rankings","Organise how hotels are grouped",t,ctx)
